const fs=require('fs');const assert=require('assert/strict');const {chromium}=require('/workspaces/zoi-city/.recovery/public-entry-release-20261006/node_modules/playwright-core');
(async()=>{const out='/tmp/zoi-public-production-20261006';fs.mkdirSync(out,{recursive:true});const browser=await chromium.launch({executablePath:'/home/codespace/.cache/ms-playwright/chromium-1234/chrome-linux64/chrome',headless:true,args:['--no-sandbox']});const report=[];try{for(const width of[390,1440])for(const theme of['dark','light']){const c=await browser.newContext({viewport:{width,height:960},reducedMotion:'reduce',serviceWorkers:'block'});await c.addInitScript(t=>localStorage.setItem('zoi_theme',t),theme);const p=await c.newPage(),errors=[],requests=[];p.on('pageerror',e=>errors.push(e.message));p.on('request',r=>requests.push(r.url()));for(const route of['/','/social/','/tickets/','/business/']){requests.length=0;const start=Date.now();await p.goto('https://www.zoi.city'+route,{waitUntil:'domcontentloaded',timeout:30000});if(route==='/'){await p.locator('.za-photo img').evaluate(i=>i.decode());assert.equal(await p.locator('.za-photo img').evaluate(i=>i.naturalWidth),3000);}else if(route==='/social/'){await p.locator('#guest-title').waitFor();assert.equal(await p.locator('#g-email').count(),0);assert(!requests.some(u=>u.includes('/assets/suite/')||u.includes('/auth/v1')||u.includes('/rest/v1')));await p.locator('[data-guest-signin]').click();await p.locator('#g-email').waitFor();await p.getByRole('button',{name:'Keep exploring'}).click();await p.locator('#guest-title').waitFor();}else if(route==='/tickets/'){await p.locator('#publicEventTitle').waitFor();assert.equal(await p.locator('#signinEmail').count(),0);assert(!requests.some(u=>u.includes('/auth/v1')||u.includes('venue-studio.mjs')));}if(route!=='/business/')assert.equal(await p.locator('#zoiCta').innerText(),'Join Zoi');else {assert(await p.getByRole('heading',{level:1}).isVisible());assert.equal(await p.locator('input[type=email]').count(),0);}assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await p.screenshot({path:out+'/'+width+'-'+theme+'-'+(route==='/'?'home':route.replaceAll('/',''))+'.png',fullPage:false});report.push({route,width,theme,visibleMs:Date.now()-start,url:p.url(),passed:true});}assert.deepEqual(errors,[]);await c.close();}fs.writeFileSync(out+'/report.json',JSON.stringify({production:true,cases:report},null,2));console.log(JSON.stringify({passed:report.length,out}));}catch(e){fs.writeFileSync(out+'/report.json',JSON.stringify({production:true,cases:report,failure:e.stack},null,2));throw e;}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
